# Synthetic inputs only; exercise the unchanged single73 source entry and offline CLI.
source('tests/helper.R');source_test_runtime();source('tests/registry-v2-fixture.R')
root<-normalizePath('.',winslash='/');work<-file.path(root,'.artifact-temp/E1-single73-synthetic');dir.create(work,recursive=TRUE,showWarnings=FALSE)
registry_v2_test_setup(root)
people<-1:20
damyda<-data.frame(patientid=people,Reg_Haemoglobin=rep(c(1,11,21,31),each=5),Reg_Creatinin_mikmoll=seq(60,79),Reg_Hoejde=rep(c(160,170,180,190),each=5),Reg_Vaegt=rep(c(60,70,80,90),each=5),Reg_Knogleforandringer=c(rep('1',4),rep('0',16)),event_date=rep(c('2024-01-01','2025-01-01'),each=10),Region=rep(c('Capital','Zealand'),each=10))
lyfo<-data.frame(patientid=people,Beh_ErDerForetagetKemo=rep(c('Y','N'),each=10),Beh_Kemoterapiregime1='CHOP',Reg_Stadium=NA_character_,IPI='SYNTHETIC_UNRECOGNISED',event_date=rep(c('2024-01-01','2025-01-01'),each=10),Region=rep(c('Capital','Zealand'),each=10))
lyfo<-rbind(lyfo,transform(lyfo,Beh_Kemoterapiregime1='bendamustin'))
cll<-data.frame(unreviewed_subject=people,Reg_BinetStadium='A',Reg_Leukocyttal=seq(20,39))
vitals<-data.frame(subject=1:81,displayname=c(rep(c('Puls','SpO2','BT systolisk','Temp'),each=20),'SYNTHETIC_PRIVATE_DESCRIPTOR'),meas_value=as.character(seq(60,140)),recorded_time=c(rep(c('2024-01-01T12:00:00Z','2025-01-01T12:00:00Z'),each=40),'invalid'),Region=c(rep(c('Capital','Zealand'),each=40),'SYNTHETIC_PRIVATE_REGION'))
patient<-data.frame(patientid=people,bmi=seq(20,39),height_in_cm=seq(160,179),weight_in_kg=seq(60,79),unreviewed_measurement=seq(1,20))
labs<-data.frame(patientid=people,analysiscode=rep(c('NPU04998','NPU01370'),each=10),value=seq(1,20),samplingdate=rep(c('2024-01-01','2025-01-01'),each=10))
inputs<-list(RKKP_DaMyDa=damyda,RKKP_LYFO=lyfo,RKKP_CLL=cll,SP_VitaleVaerdier=vitals,SP_PatientInfo=patient,SP_Laboratorieproever=labs)
for(name in names(inputs))write.csv(inputs[[name]],file.path(work,paste0(name,'.csv')),row.names=FALSE,na='')
keys<-data.frame(table_name=c('RKKP_DaMyDa','RKKP_LYFO','SP_VitaleVaerdier','SP_PatientInfo','SP_Laboratorieproever'),person_key=c('patientid','patientid','subject','patientid','patientid'),reviewed=TRUE);write.csv(keys,file.path(work,'keys.csv'),row.names=FALSE)
map<-data.frame(table_name=names(inputs),source_type='file',source=file.path(work,paste0(names(inputs),'.csv')),priority=seq_along(inputs),profile_mode='full',domain=c('RKKP','RKKP','RKKP','SP','SP','SP'),subdomain=c('DaMyDa','LYFO','CLL','Vitals','Patient information','Laboratory'),atlas_role='synthetic_validation')
write.table(map,file.path(work,'sources.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
Sys.setenv(DALYCARE_SYNTHETIC_VALIDATION='TRUE',DALYCARE_REGISTRY_PERSON_KEYS_FILE=file.path(work,'keys.csv'),DALYCARE_ATLAS_SOURCE_MAP=file.path(work,'sources.tsv'),DALYCARE_ATLAS_OUTPUT_ROOT=file.path(work,'runs'),DALYCARE_ATLAS_MODE='report')
Sys.unsetenv('DALYCARE_ATLAS_SOURCE_ONLY')
timing<-system.time(sys.source(file.path(root,'RUN_DALYCARE_ATLAS_73_SOURCE.R'),envir=new.env(parent=.GlobalEnv)))
if(isTRUE(dalycare_atlas_failed))stop('Synthetic single73 fixture did not publish')
run<-dalycare_atlas_result$run_dir
stopifnot(file.exists(file.path(run,'site.zip')))
registry<-read_public_table(file.path(run,'site'),'registry_field_summaries')
stopifnot(any(vapply(registry,function(r)identical(r$summary_status,'published')&&identical(r$summary_kind,'numeric'),logical(1)))||any(vapply(registry,function(r)!is.null(r$approximate_mean),logical(1))))
stopifnot(any(vapply(registry,function(r)identical(r$summary_status,'published')&&nzchar(r$category_counts_json %||% ''),logical(1))))
before<-read_public_table(file.path(run,'site'),'column_profiles')
rebuild<-system.time({status<-system2(file.path(R.home('bin'),if(.Platform$OS.type=='windows')'Rscript.exe' else 'Rscript'),shQuote(c(file.path(root,'scripts/rebuild_atlas_from_outputs.R'),run,root)),stdout=file.path(work,'offline-rebuild.log'),stderr=file.path(work,'offline-rebuild.log'));stopifnot(status==0L)})
stopifnot(identical(before,read_public_table(file.path(run,'site'),'column_profiles')))
writeLines(c(paste('run',normalizePath(run,winslash='/')),paste('single73_seconds',timing[['elapsed']]),paste('offline_seconds',rebuild[['elapsed']]),'Fixture limits: database query-failed and live NGC behavior are covered separately; these file-backed synthetic sources do not fabricate query failure.'),file.path(work,'result.txt'))
cat('PASS actual single73 synthetic producer and unchanged offline rebuild: ',run,'\n')
